return-response.set-body:
@{
        var host = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
        var clientId = "{{apim-app-client-id}}";
        var tenantId = "{{tenant-id}}";
        return "{"
          + "\"resource\":\"" + host + "/mcp\","
          + "\"authorization_servers\":[\"https://login.microsoftonline.com/" + tenantId + "/v2.0\"],"
          + "\"scopes_supported\":[\"api://" + clientId + "/user_impersonation\"],"
          + "\"bearer_methods_supported\":[\"header\"],"
          + "\"resource_name\":\"Azure DevOps MCP (via APIM)\""
          + "}";
      }
